import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from tally import parse_amount  # noqa: E402


class ParseAmountTest(unittest.TestCase):
    def test_nineteen_ninety_nine_is_exact(self):
        self.assertEqual(parse_amount("19.99"), 1999)

    def test_ten_cents(self):
        self.assertEqual(parse_amount("0.10"), 10)

    def test_whole_number(self):
        self.assertEqual(parse_amount("5"), 500)


if __name__ == "__main__":
    unittest.main()
